+// for the test's lifetime keeps the port ours.
+func deadPinningClient(t *testing.T) *http.Client {
+	t.Helper()
+	var lc net.ListenConfig
+	l, err := lc.Listen(t.Context(), "tcp", "127.0.0.1:0")
