		for {
			c, err := l.Accept()
			if err != nil {
				return
			}
			_ = c.Close()
		}
	}()
	return &http.Client{
		Transport: rewritingTransport{base: newTestTransport(t), scheme: "http", host: l.Addr().String()},
	}
